export function getTeamByCode(code: string): Team | undefined { return TEAMS.find(t => t.id === code); }
export function getTeamsByGroup(group: string): Team[] { return TEAMS.filter(t => t.group === group).sort((a,b) => b.projectedPoints - a.projectedPoints); }
export function getMatchesByGroup(group: string): Match[] { return MATCHES.filter(m => m.group === group); }
export function getPlayersByCountry(country: string): Player[] { return PLAYERS.filter(p => p.country === country); }
